import { signalAddressKey } from 'zapo-js/protocol';
import { decodeSignalRemoteIdentity, toSignalAddressParts } from 'zapo-js/signal';
import { asNumber, asString, resolvePositive } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
import { repeatSqlToken } from './sql-utils.js';
const DEFAULTS = Object.freeze({
    identityBatchSize: 250
});
export class WaIdentitySqliteStore extends BaseSqliteStore {
    constructor(options, storeOptions = {}) {
        super(options, ['signal']);
        this.identityBatchSize = resolvePositive(storeOptions.identityBatchSize, DEFAULTS.identityBatchSize, 'signal.sqlite.identityBatchSize');
    }
    async getRemoteIdentity(address) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        const row = db.get(`SELECT identity_key
             FROM signal_identity
             WHERE session_id = ? AND user = ? AND server = ? AND device = ?`, [this.options.sessionId, target.user, target.server, target.device]);
        return row ? decodeSignalRemoteIdentity(row.identity_key) : null;
    }
    async getRemoteIdentities(addresses) {
        if (addresses.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const targets = new Array(addresses.length);
        for (let index = 0; index < addresses.length; index += 1) {
            targets[index] = toSignalAddressParts(addresses[index]);
        }
        const byAddressKey = new Map();
        for (let start = 0; start < targets.length; start += this.identityBatchSize) {
            const end = Math.min(start + this.identityBatchSize, targets.length);
            const batchLength = end - start;
            const filters = repeatSqlToken('(user = ? AND server = ? AND device = ?)', batchLength, ' OR ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                const target = targets[index];
                params.push(target.user, target.server, target.device);
            }
            const rows = db.all(`SELECT user, server, device, identity_key
                 FROM signal_identity
                 WHERE session_id = ? AND (${filters})`, params);
            for (const row of rows) {
                byAddressKey.set(signalAddressKey({
                    user: asString(row.user, 'signal_identity.user'),
                    server: asString(row.server, 'signal_identity.server'),
                    device: asNumber(row.device, 'signal_identity.device')
                }), decodeSignalRemoteIdentity(row.identity_key));
            }
        }
        const identities = new Array(targets.length);
        for (let index = 0; index < targets.length; index += 1) {
            identities[index] = byAddressKey.get(signalAddressKey(targets[index])) ?? null;
        }
        return identities;
    }
    async setRemoteIdentity(address, identityKey) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        this.upsertRemoteIdentity(db, target, identityKey);
    }
    async setRemoteIdentities(entries) {
        if (entries.length === 0) {
            return;
        }
        await this.withTransaction((db) => {
            for (let index = 0; index < entries.length; index += 1) {
                const entry = entries[index];
                const target = toSignalAddressParts(entry.address);
                this.upsertRemoteIdentity(db, target, entry.identityKey);
            }
        });
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM signal_identity WHERE session_id = ?', [this.options.sessionId]);
        });
    }
    upsertRemoteIdentity(db, target, identityKey) {
        db.run(`INSERT INTO signal_identity (
                session_id,
                user,
                server,
                device,
                identity_key
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(session_id, user, server, device) DO UPDATE SET
                identity_key=excluded.identity_key`, [this.options.sessionId, target.user, target.server, target.device, identityKey]);
    }
}
